parameters.query:
SELECT tipo, contexto FROM mayordomo_eventos
WHERE usuario_id = $1
  AND tipo IN ('calendar.creado','recordatorio.creado')
  AND (
    (contexto->>'fecha') IS NOT NULL AND (contexto->>'fecha')::date IN (current_date, current_date + 1)
    OR (
      (contexto->>'fecha_inicio') IS NOT NULL AND (
        current_date BETWEEN (contexto->>'fecha_inicio')::date AND (contexto->>'fecha_fin')::date
        OR current_date + 1 BETWEEN (contexto->>'fecha_inicio')::date AND (contexto->>'fecha_fin')::date
      )
    )
  );

