const disponibles = $('Contar preguntas disponibles').first().json.disponibles;
const yaHechas = $('Preguntas ya hechas').all().map(i => i.json.pregunta);
const faltan = 3 - disponibles;
const listaYaHechas = yaHechas.length ? yaHechas.map(p => `- ${p}`).join('\n') : '(ninguna todavia)';
const prompt = `Genera exactamente ${faltan} preguntas personales nuevas para conocer mejor a Basilio (gustos, vida, habitos, relaciones, no preguntas de trabajo ni de proyectos). Que no se parezcan a estas que ya se le han preguntado:\n${listaYaHechas}\n\nResponde SOLO un array JSON de strings, nada mas, sin markdown. Ejemplo de formato: ["pregunta 1", "pregunta 2"]`;
return [{ json: { prompt } }];

const raw = $json.stdout ?? '';
let texto = raw;
try {
  const parsed = JSON.parse(raw);
  texto = parsed.result ?? parsed.text ?? parsed.response ?? parsed.output ?? raw;
} catch (e) {}
let preguntas = [];
try {
  const match = String(texto).match(/\[[\s\S]*\]/);
  preguntas = match ? JSON.parse(match[0]) : [];
} catch (e) { preguntas = []; }
return preguntas.filter(p => typeof p === 'string' && p.trim()).map(p => ({ json: { pregunta: p.trim() } }));

const recuerdos = $('Recuerdos 24h').all().map(i => i.json).filter(r => r.categoria);
const eventos = $('Eventos 24h').all().map(i => i.json).filter(e => e.tipo);
const estadoVideos = ($('Estado videos Levstamp').first()?.json.stdout) || 'No se pudo comprobar el estado de los videos.';
const proyectos = $('Proyectos activos').all().map(i => i.json).filter(p => p.nombre);
const diaLibre = $('Dia libre hoy').all().map(i => i.json).filter(d => d.contenido);
const recordatorios = $('Recordatorios hoy y manana').all().map(i => i.json).filter(r => r.tipo);
const preguntas = $('Elegir preguntas personales').all().map(i => i.json).filter(p => p.pregunta);

if (diaLibre.length) {
  const prompt = `Hoy el usuario marco como dia libre: "${diaLibre[0].contenido}". Escribe una frase corta y natural en espanol confirmando que hoy no se le propone nada, que descanse. Nada mas, sin markdown, sin preguntas.`;
  return [{ json: { prompt } }];
}

let datos = '';
if (recuerdos.length) {
  datos += 'Recuerdos guardados en las ultimas 24h:\n' + recuerdos.map(r => `- [${r.categoria}] ${r.contenido}`).join('\n') + '\n\n';
}
if (eventos.length) {
  datos += 'Eventos registrados en las ultimas 24h:\n' + eventos.map(e => `- [${e.tipo}] ${JSON.stringify(e.contexto)}`).join('\n') + '\n\n';
}
if (!recuerdos.length && !eventos.length) { datos += 'Sin actividad registrada en las ultimas 24 horas.\n\n'; }

if (proyectos.length) {
  datos += 'Estado real de los proyectos activos (bloqueadores y pendientes_nuevos):\n';
  datos += proyectos.map(p => `- ${p.nombre}: ${JSON.stringify(p.atributos)}`).join('\n');
  datos += '\n\n';
}

datos += `Estado real de los videos de Levstamp, comprobado contra disco esta misma mañana (esto es PARTE del proyecto Levstamp, no algo aparte):\n${estadoVideos}\n\n`;

if (recordatorios.length) {
  datos += 'Recordatorios/eventos para HOY o MAÑANA (fechas reales):\n';
  datos += recordatorios.map(r => `- [${r.tipo}] ${JSON.stringify(r.contexto)}`).join('\n');
  datos += '\n\n';
} else {
  datos += 'No hay recordatorios ni eventos para hoy ni para mañana.\n\n';
}

const preguntasTexto = preguntas.length
  ? preguntas.map(p => `- ${p.pregunta}`).join('\n')
  : '(no hay preguntas nuevas disponibles hoy)';

const prompt = `Eres un asistente de redaccion. No tienes herramientas, no puedes ejecutar nada, solo responder texto.

Aqui tienes los datos reales de Basilio para el briefing de hoy (no los inventes ni los cuestiones):

${datos}

Escribe el briefing con esta estructura exacta, en español, sin markdown ni simbolos de formato:

1. Si hay recordatorios o eventos para hoy o mañana, listalos primero, claramente, con fecha. Si no hay ninguno, dilo en una frase corta.
2. Si hay "Recuerdos guardados en las ultimas 24h", Basilio las escribe sueltas y desordenadas a lo largo del dia -- tu trabajo aqui es limpiarlas: agrupa las que hablen de lo mismo, quita repeticiones, descarta ruido sin contenido, y reescribelas como ideas claras y breves (no copies el texto crudo tal cual). Si alguna nota claramente pertenece a un proyecto de la lista de abajo, no la repitas aqui, mencionala en el punto de ese proyecto. Si no hay recuerdos nuevos, omite este punto sin decir nada.
3. Por cada proyecto activo, un resumen breve y concreto de su situacion: bloqueadores reales y pendientes nuevos, nombrando las tareas tal cual estan guardadas, no genérico. Para Levstamp, incluye ADEMAS (no en vez de) el estado de los videos: cuantos pendientes y cuales priorizarias.
4. Una propuesta de que hacer hoy en 3 niveles -- minima (poco tiempo/energia), normal, y extendida (dia con mas energia) -- basada en todo lo anterior (proyectos + videos + recordatorios). Se concreto.
5. Termina con estas 3 preguntas personales, tal cual, sin modificarlas ni inventar otras:
${preguntasTexto}

Responde solo el texto final con esa estructura, nada mas.`;

return [{ json: { prompt } }];

const raw = $json.stdout ?? '';
let texto = raw;
try {
  const parsed = JSON.parse(raw);
  texto = parsed.result ?? parsed.text ?? parsed.response ?? parsed.output ?? raw;
} catch (e) { /* si no es JSON, se queda el texto crudo */ }
return [{ json: { texto: String(texto).trim() } }];
